#include <cstring>
#include <cstdint>
#include <string>
#include <vector>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <arpa/inet.h>

namespace secure_msg {

static const unsigned char HMAC_KEY[32] = {
    0x4a, 0x7b, 0x3c, 0x9d, 0x2e, 0x5f, 0x10, 0xa1,
    0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x07, 0x18, 0x29,
    0x3a, 0x4b, 0x5c, 0x6d, 0x7e, 0x8f, 0x90, 0xa1,
    0xb2, 0xc3, 0xd4, 0xe5, 0xf6, 0x07, 0x18, 0x29
};

struct MessageHeader {
    uint32_t magic;        // 0xDEADBEEF
    int32_t  payload_len;  // length of payload (signed for compatibility with legacy systems)
    uint32_t msg_type;     // message type identifier
    uint8_t  hmac[32];     // HMAC-SHA256 of payload
};

static const uint32_t MAGIC = 0xDEADBEEF;
static const size_t MAX_PAYLOAD = 65536;

// Compute HMAC-SHA256 over data
bool compute_hmac(const uint8_t* data, size_t len, uint8_t* out) {
    unsigned int hmac_len = 0;
    unsigned char* result = HMAC(EVP_sha256(), HMAC_KEY, sizeof(HMAC_KEY),
                                  data, len, out, &hmac_len);
    return result != nullptr && hmac_len == 32;
}

// Verify HMAC of received payload
bool verify_payload_hmac(const uint8_t* payload, int32_t payload_len,
                         const uint8_t* expected_hmac) {
    uint8_t computed[32];
    // Defensive check: payload length must be reasonable
    if (payload_len > (int32_t)MAX_PAYLOAD) {
        return false;
    }
    if (payload == nullptr) {
        return false;
    }
    // Compute HMAC over the payload bytes
    if (!compute_hmac(payload, (size_t)payload_len, computed)) {
        return false;
    }
    // Constant-time comparison
    return CRYPTO_memcmp(computed, expected_hmac, 32) == 0;
}

class SecureMessageServer {
private:
    int server_fd_;
    uint16_t port_;
    bool running_;

    struct ClientSession {
        int fd;
        std::string username;
        bool authenticated;
        uint32_t msg_count;
    };

    std::vector<ClientSession> sessions_;

    // Process authenticated message
    void process_message(ClientSession& session, uint32_t msg_type,
                        const uint8_t* payload, int32_t payload_len) {
        if (!session.authenticated && msg_type != 1) {
            return; // Must authenticate first
        }

        switch (msg_type) {
            case 1: // AUTH
                if (payload_len >= 4 && payload_len <= 64) {
                    session.username = std::string((char*)payload, payload_len);
                    session.authenticated = true;
                }
                break;
            case 2: // DATA
                session.msg_count++;
                // Process data payload
                handle_data(session, payload, payload_len);
                break;
            case 3: // PING
                send_pong(session);
                break;
        }
    }

    void handle_data(ClientSession& session, const uint8_t* data, int32_t len) {
        // Store or forward data
        if (len > 0 && len <= (int32_t)MAX_PAYLOAD) {
            // Process the data buffer
            std::vector<uint8_t> buffer(data, data + len);
            // ... application logic ...
        }
    }

    void send_pong(ClientSession& session) {
        uint8_t pong[] = {0x50, 0x4F, 0x4E, 0x47};
        send(session.fd, pong, sizeof(pong), MSG_NOSIGNAL);
    }

public:
    SecureMessageServer(uint16_t port) : server_fd_(-1), port_(port), running_(false) {}

    ~SecureMessageServer() {
        running_ = false;
        if (server_fd_ >= 0) close(server_fd_);
        for (auto& s : sessions_) {
            if (s.fd >= 0) close(s.fd);
        }
    }

    bool start() {
        server_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (server_fd_ < 0) return false;

        int opt = 1;
        setsockopt(server_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_addr.s_addr = htonl(INADDR_LOOPBACK);
        addr.sin_port = htons(port_);

        if (bind(server_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) return false;
        if (listen(server_fd_, 5) < 0) return false;

        running_ = true;
        return true;
    }

    // Main message receive and validation loop
    void handle_client(int client_fd) {
        ClientSession session{client_fd, "", false, 0};
        sessions_.push_back(session);

        while (running_) {
            MessageHeader hdr{};
            ssize_t n = recv(client_fd, &hdr, sizeof(hdr), MSG_WAITALL);
            if (n != sizeof(hdr)) break;

            // Validate magic
            if (hdr.magic != MAGIC) break;

            // Validate payload length bounds
            if (hdr.payload_len > (int32_t)MAX_PAYLOAD) break;

            // Allocate and receive payload
            std::vector<uint8_t> payload(hdr.payload_len);
            if (hdr.payload_len > 0) {
                n = recv(client_fd, payload.data(), hdr.payload_len, MSG_WAITALL);
                if (n != hdr.payload_len) break;
            }

            // Verify HMAC integrity
            if (!verify_payload_hmac(payload.data(), hdr.payload_len, hdr.hmac)) {
                break; // HMAC verification failed
            }

            // Process verified message
            process_message(session, hdr.msg_type, payload.data(), hdr.payload_len);
        }

        close(client_fd);
    }
};

} // namespace secure_msg

int main() {
    secure_msg::SecureMessageServer server(8443);
    if (!server.start()) return 1;

    struct sockaddr_in client_addr{};
    socklen_t client_len = sizeof(client_addr);
    int client_fd = accept(4, (struct sockaddr*)&client_addr, &client_len);
    if (client_fd >= 0) {
        server.handle_client(client_fd);
    }
    return 0;
}
